using Microsoft.EntityFrameworkCore;
namespace TajerOS;

public sealed class Product { public string Id { get; set; } = ""; public string Name { get; set; } = ""; public string ArabicName { get; set; } = ""; public string Unit { get; set; } = "carton"; public decimal Stock { get; set; } public decimal AverageCost { get; set; } public decimal ReorderPoint { get; set; } = 10; public int LeadDays { get; set; } = 3; }
public sealed class Proposal { public Guid Id { get; set; } = Guid.NewGuid(); public string Kind { get; set; } = "purchase"; public string ProductId { get; set; } = "oil"; public decimal Quantity { get; set; } public decimal? Total { get; set; } public string Status { get; set; } = "pending"; public string Source { get; set; } = ""; public string Warnings { get; set; } = ""; public string CreatedBy { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public int Version { get; set; } = 1; public string RequestKey { get; set; } = ""; }
public sealed class Ledger { public Guid Id { get; set; } = Guid.NewGuid(); public Guid ProposalId { get; set; } public string ProductId { get; set; } = ""; public string Kind { get; set; } = ""; public decimal Quantity { get; set; } public decimal Total { get; set; } public decimal Cost { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public Guid? OriginalSaleId { get; set; } }
public sealed class Workflow { public Guid Id { get; set; } = Guid.NewGuid(); public string Name { get; set; } = "Returns department"; public string Kind { get; set; } = "returns"; public string Status { get; set; } = "pending"; public string SchemaJson { get; set; } = "{}"; public string Description { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public sealed class WorkflowRecord { public Guid Id { get; set; } = Guid.NewGuid(); public Guid WorkflowId { get; set; } public Guid SaleId { get; set; } public decimal Quantity { get; set; } public string Reason { get; set; } = ""; public string Status { get; set; } = "pending"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public sealed class BusinessDocument { public Guid Id { get; set; } = Guid.NewGuid(); public string Title { get; set; } = ""; public string Text { get; set; } = ""; public string Source { get; set; } = "Company policy"; }
public sealed class Audit { public long Id { get; set; } public string Actor { get; set; } = ""; public string Action { get; set; } = ""; public string EntityId { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public sealed class Operator { public int Id { get; set; } public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = "owner"; }
public sealed class AppDb(DbContextOptions<AppDb> options) : DbContext(options)
{
    public DbSet<Product> Products => Set<Product>(); public DbSet<Proposal> Proposals => Set<Proposal>(); public DbSet<Ledger> Ledger => Set<Ledger>(); public DbSet<Workflow> Workflows => Set<Workflow>(); public DbSet<WorkflowRecord> WorkflowRecords => Set<WorkflowRecord>(); public DbSet<BusinessDocument> Documents => Set<BusinessDocument>(); public DbSet<Audit> Audits => Set<Audit>(); public DbSet<Operator> Operators => Set<Operator>();
    protected override void OnModelCreating(ModelBuilder b) { b.Entity<Proposal>().Property(x => x.Version).IsConcurrencyToken(); b.Entity<Proposal>().HasIndex(x => x.RequestKey).IsUnique(); b.Entity<Ledger>().HasIndex(x => x.ProposalId).IsUnique(); b.Entity<Operator>().HasIndex(x => x.Email).IsUnique(); foreach (var e in b.Model.GetEntityTypes()) foreach (var p in e.GetProperties()) if (p.ClrType == typeof(decimal) || p.ClrType == typeof(decimal?)) { p.SetPrecision(18); p.SetScale(4); } }
}
public sealed class WriteGate { public SemaphoreSlim Lock { get; } = new(1, 1); }
